   415  otError MleRouter::SendAdvertisement(void)
   416  {
   417      otError      error = OT_ERROR_NONE;
   418      Ip6::Address destination;
   419      Message *    message = NULL;
   420
   421      // Suppress MLE Advertisements when trying to attach to a better partition.
   422      //
   423      // Without this suppression, a device may send an MLE Advertisement before receiving the MLE Child ID Response.
   424      // The candidate parent then removes the attaching device because the Source Address TLV includes an RLOC16 that
   425      // indicates a Router role (i.e. a Child ID equal to zero).
   426      VerifyOrExit(mAttachState == kAttachStateIdle);
   427
   428      // Suppress MLE Advertisements when transitioning to the router role.
   429      //
   430      // When trying to attach to a new partition, sending out advertisements as a REED can cause already-attached
   431      // children to detach.
   432      VerifyOrExit(!mAddressSolicitPending);
   433
   434      VerifyOrExit((message = NewMleMessage()) != NULL, error = OT_ERROR_NO_BUFS);
   435      SuccessOrExit(error = AppendHeader(*message, Header::kCommandAdvertisement));
   436      SuccessOrExit(error = AppendSourceAddress(*message));
   437      SuccessOrExit(error = AppendLeaderData(*message));
   438
   439      switch (mRole)
   440      {
   441      case OT_DEVICE_ROLE_DISABLED:
   442      case OT_DEVICE_ROLE_DETACHED:
   443          assert(false);
   444          break;
   445
   446      case OT_DEVICE_ROLE_CHILD:
   447          break;
   448
   449      case OT_DEVICE_ROLE_ROUTER:
   450      case OT_DEVICE_ROLE_LEADER:
   451          SuccessOrExit(error = AppendRoute(*message));
   452          break;
   453      }
   454
   455      memset(&destination, 0, sizeof(destination));
   456      destination.mFields.m16[0] = HostSwap16(0xff02);
   457      destination.mFields.m16[7] = HostSwap16(0x0001);
   458      SuccessOrExit(error = SendMessage(*message, destination));
   459
   460      LogMleMessage("Send Advertisement", destination);
   461
   462  exit:
   463
   464      if (error != OT_ERROR_NONE && message != NULL)
   465      {
   466          message->Free();
   467      }
   468
   469      return error;
   470  }
