   472  otError MleRouter::SendLinkRequest(Neighbor *aNeighbor)
   473  {
   474      static const uint8_t detachedTlvs[]      = {Tlv::kAddress16, Tlv::kRoute};
   475      static const uint8_t routerTlvs[]        = {Tlv::kLinkMargin};
   476      static const uint8_t validNeighborTlvs[] = {Tlv::kLinkMargin, Tlv::kRoute};
   477      otError              error               = OT_ERROR_NONE;
   478      Message *            message;
   479      Ip6::Address         destination;
   480
   481      memset(&destination, 0, sizeof(destination));
   482
   483      VerifyOrExit((message = NewMleMessage()) != NULL, error = OT_ERROR_NO_BUFS);
   484      SuccessOrExit(error = AppendHeader(*message, Header::kCommandLinkRequest));
   485      SuccessOrExit(error = AppendVersion(*message));
   486
   487      switch (mRole)
   488      {
   489      case OT_DEVICE_ROLE_DISABLED:
   490          assert(false);
   491          break;
   492
   493      case OT_DEVICE_ROLE_DETACHED:
   494          SuccessOrExit(error = AppendTlvRequest(*message, detachedTlvs, sizeof(detachedTlvs)));
   495          break;
   496
   497      case OT_DEVICE_ROLE_CHILD:
   498          SuccessOrExit(error = AppendSourceAddress(*message));
   499          SuccessOrExit(error = AppendLeaderData(*message));
   500          break;
   501
   502      case OT_DEVICE_ROLE_ROUTER:
   503      case OT_DEVICE_ROLE_LEADER:
   504          if (aNeighbor == NULL || aNeighbor->GetState() != Neighbor::kStateValid)
   505          {
   506              SuccessOrExit(error = AppendTlvRequest(*message, routerTlvs, sizeof(routerTlvs)));
   507          }
   508          else
   509          {
   510              SuccessOrExit(error = AppendTlvRequest(*message, validNeighborTlvs, sizeof(validNeighborTlvs)));
   511          }
   512
   513          SuccessOrExit(error = AppendSourceAddress(*message));
   514          SuccessOrExit(error = AppendLeaderData(*message));
   515          break;
   516      }
   517
   518  #if OPENTHREAD_CONFIG_ENABLE_TIME_SYNC
   519      SuccessOrExit(error = AppendTimeRequest(*message));
   520  #endif
   520  #endif
   521
   522      if (aNeighbor == NULL)
   523      {
   524          Random::FillBuffer(mChallenge, sizeof(mChallenge));
   525
   526          mChallengeTimeout = (((2 * kMaxResponseDelay) + kStateUpdatePeriod - 1) / kStateUpdatePeriod);
   527
   528          SuccessOrExit(error = AppendChallenge(*message, mChallenge, sizeof(mChallenge)));
   529          destination.mFields.m8[0]  = 0xff;
   530          destination.mFields.m8[1]  = 0x02;
   531          destination.mFields.m8[15] = 2;
   532      }
   533      else
   534      {
   535          if (aNeighbor->GetState() != Neighbor::kStateValid)
   536          {
   537              aNeighbor->GenerateChallenge();
   538              SuccessOrExit(error = AppendChallenge(*message, aNeighbor->GetChallenge(), aNeighbor->GetChallengeSize()));
   539          }
   540          else
   541          {
   542              uint8_t challenge[ChallengeTlv::kMaxSize];
   543
   544              Random::FillBuffer(challenge, sizeof(challenge));
   545              SuccessOrExit(error = AppendChallenge(*message, challenge, sizeof(challenge)));
   546          }
   547
   548          destination.mFields.m16[0] = HostSwap16(0xfe80);
   549          destination.SetIid(aNeighbor->GetExtAddress());
   550      }
   551
   552      SuccessOrExit(error = SendMessage(*message, destination));
   553
   554      LogMleMessage("Send Link Request", destination);
   555
   556  exit:
   557
   558      if (error != OT_ERROR_NONE && message != NULL)
   559      {
   560          message->Free();
   561      }
   562
   563      return error;
   564  }
