   566  otError MleRouter::HandleLinkRequest(const Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
   567  {
   568      otError          error    = OT_ERROR_NONE;
   569      Neighbor *       neighbor = NULL;
   570      Mac::ExtAddress  macAddr;
   571      ChallengeTlv     challenge;
   572      VersionTlv       version;
   573      LeaderDataTlv    leaderData;
   574      SourceAddressTlv sourceAddress;
   575      TlvRequestTlv    tlvRequest;
   576      uint16_t         rloc16;
   577  #if OPENTHREAD_CONFIG_ENABLE_TIME_SYNC
   578      TimeRequestTlv timeRequest;
   579  #endif
   580
   581      LogMleMessage("Receive Link Request", aMessageInfo.GetPeerAddr());
   582
   583      VerifyOrExit(mRole == OT_DEVICE_ROLE_ROUTER || mRole == OT_DEVICE_ROLE_LEADER, error = OT_ERROR_INVALID_STATE);
   584
   585      VerifyOrExit(mAttachState == kAttachStateIdle, error = OT_ERROR_INVALID_STATE);
   586
   587      aMessageInfo.GetPeerAddr().ToExtAddress(macAddr);
   588
   589      // Challenge
   590      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kChallenge, sizeof(challenge), challenge));
   591      VerifyOrExit(challenge.IsValid(), error = OT_ERROR_PARSE);
   592
   593      // Version
   594      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kVersion, sizeof(version), version));
   595      VerifyOrExit(version.IsValid() && version.GetVersion() >= kThreadVersion, error = OT_ERROR_PARSE);
   596
   597      // Leader Data
   598      if (Tlv::GetTlv(aMessage, Tlv::kLeaderData, sizeof(leaderData), leaderData) == OT_ERROR_NONE)
   599      {
   600          VerifyOrExit(leaderData.IsValid(), error = OT_ERROR_PARSE);
   601          VerifyOrExit(leaderData.GetPartitionId() == mLeaderData.GetPartitionId(), error = OT_ERROR_INVALID_STATE);
   602      }
   603
   604      // Source Address
   605      if (Tlv::GetTlv(aMessage, Tlv::kSourceAddress, sizeof(sourceAddress), sourceAddress) == OT_ERROR_NONE)
   606      {
   607          VerifyOrExit(sourceAddress.IsValid(), error = OT_ERROR_PARSE);
   608
   609          rloc16 = sourceAddress.GetRloc16();
   610
   611          if ((neighbor = GetNeighbor(macAddr)) != NULL && neighbor->GetRloc16() != rloc16)
   612          {
   613              // remove stale neighbors
   614              RemoveNeighbor(*neighbor);
   615              neighbor = NULL;
   616          }
   617
   618          if (IsActiveRouter(rloc16))
   619          {
   620              // source is a router
   621              neighbor = mRouterTable.GetRouter(GetRouterId(rloc16));
   622              VerifyOrExit(neighbor != NULL, error = OT_ERROR_PARSE);
   623              VerifyOrExit(neighbor->GetState() != Neighbor::kStateLinkRequest, error = OT_ERROR_ALREADY);
   624
   625              if (neighbor->GetState() != Neighbor::kStateValid)
   626              {
   627                  const otThreadLinkInfo *linkInfo = static_cast<const otThreadLinkInfo *>(aMessageInfo.GetLinkInfo());
   628
   629                  neighbor->SetExtAddress(macAddr);
   630                  neighbor->GetLinkInfo().Clear();
   631                  neighbor->GetLinkInfo().AddRss(GetNetif().GetMac().GetNoiseFloor(), linkInfo->mRss);
   632                  neighbor->ResetLinkFailures();
   633                  neighbor->SetLastHeard(TimerMilli::GetNow());
   634                  neighbor->SetState(Neighbor::kStateLinkRequest);
   635              }
   636              else
   637              {
   638                  VerifyOrExit(neighbor->GetExtAddress() == macAddr);
   639              }
   640          }
   641          else
   642          {
   643              // source is not a router
   644              neighbor = NULL;
   645          }
   646      }
   647      else
   648      {
   649          // lack of source address indicates router coming out of reset
   650          VerifyOrExit((neighbor = GetNeighbor(macAddr)) != NULL && neighbor->GetState() == Neighbor::kStateValid &&
   651                           IsActiveRouter(neighbor->GetRloc16()),
   652                       error = OT_ERROR_DROP);
   653      }
   654
   655      // TLV Request
   656      if (Tlv::GetTlv(aMessage, Tlv::kTlvRequest, sizeof(tlvRequest), tlvRequest) == OT_ERROR_NONE)
   657      {
   658          VerifyOrExit(tlvRequest.IsValid(), error = OT_ERROR_PARSE);
   659      }
   660      else
   661      {
   662          tlvRequest.SetLength(0);
   663      }
   664
   665  #if OPENTHREAD_CONFIG_ENABLE_TIME_SYNC
   666      if (Tlv::GetTlv(aMessage, Tlv::kTimeRequest, sizeof(timeRequest), timeRequest) == OT_ERROR_NONE)
   667      {
   668          neighbor->SetTimeSyncEnabled(true);
   669      }
   670      else
   671      {
   672          neighbor->SetTimeSyncEnabled(false);
   673      }
   674  #endif
   675
   676      SuccessOrExit(error = SendLinkAccept(aMessageInfo, neighbor, tlvRequest, challenge));
   677
   678  exit:
   679      return error;
   680  }
   681
   682  otError MleRouter::SendLinkAccept(const Ip6::MessageInfo &aMessageInfo,
   683                                    Neighbor *              aNeighbor,
   684                                    const TlvRequestTlv &   aTlvRequest,
   685                                    const ChallengeTlv &    aChallenge)
   686  {
   687      otError                 error        = OT_ERROR_NONE;
   688      const otThreadLinkInfo *linkInfo     = static_cast<const otThreadLinkInfo *>(aMessageInfo.GetLinkInfo());
   689      static const uint8_t    routerTlvs[] = {Tlv::kLinkMargin};
   690      Message *               message;
   691      Header::Command         command;
   692      uint8_t                 linkMargin;
   693
   694      command = (aNeighbor == NULL || aNeighbor->GetState() == Neighbor::kStateValid)
   695                    ? Header::kCommandLinkAccept
   696                    : Header::kCommandLinkAcceptAndRequest;
   697
   698      VerifyOrExit((message = NewMleMessage()) != NULL, error = OT_ERROR_NO_BUFS);
   699      SuccessOrExit(error = AppendHeader(*message, command));
   700      SuccessOrExit(error = AppendVersion(*message));
   701      SuccessOrExit(error = AppendSourceAddress(*message));
   702      SuccessOrExit(error = AppendResponse(*message, aChallenge.GetChallenge(), aChallenge.GetLength()));
   703      SuccessOrExit(error = AppendLinkFrameCounter(*message));
   704      SuccessOrExit(error = AppendMleFrameCounter(*message));
   705
   706      // always append a link margin, regardless of whether or not it was requested
   707      linkMargin = LinkQualityInfo::ConvertRssToLinkMargin(GetNetif().GetMac().GetNoiseFloor(), linkInfo->mRss);
   708
   709      SuccessOrExit(error = AppendLinkMargin(*message, linkMargin));
   710
   711      if (aNeighbor != NULL && IsActiveRouter(aNeighbor->GetRloc16()))
   712      {
   713          SuccessOrExit(error = AppendLeaderData(*message));
   714      }
   715
   716      for (uint8_t i = 0; i < aTlvRequest.GetLength(); i++)
   717      {
   718          switch (aTlvRequest.GetTlvs()[i])
   719          {
   720          case Tlv::kRoute:
   721              SuccessOrExit(error = AppendRoute(*message));
   722              break;
   723
   724          case Tlv::kAddress16:
   725              VerifyOrExit(aNeighbor != NULL, error = OT_ERROR_DROP);
   726              SuccessOrExit(error = AppendAddress16(*message, aNeighbor->GetRloc16()));
   727              break;
   728
   729          case Tlv::kLinkMargin:
   730              break;
   731
   732          default:
   733              ExitNow(error = OT_ERROR_DROP);
   734          }
   735      }
   736
   737      if (aNeighbor != NULL && aNeighbor->GetState() != Neighbor::kStateValid)
   738      {
   739          aNeighbor->GenerateChallenge();
   740
   741          SuccessOrExit(error = AppendChallenge(*message, aNeighbor->GetChallenge(), aNeighbor->GetChallengeSize()));
   742          SuccessOrExit(error = AppendTlvRequest(*message, routerTlvs, sizeof(routerTlvs)));
   743          aNeighbor->SetLastHeard(TimerMilli::GetNow());
   744          aNeighbor->SetState(Neighbor::kStateLinkRequest);
   745      }
   746
   747  #if OPENTHREAD_CONFIG_ENABLE_TIME_SYNC
   748      if (aNeighbor->IsTimeSyncEnabled())
   749      {
   750          message->SetTimeSync(true);
   751      }
   752  #endif
   753
   754      if (aMessageInfo.GetSockAddr().IsMulticast())
   755      {
   756          SuccessOrExit(error = AddDelayedResponse(*message, aMessageInfo.GetPeerAddr(),
   757                                                   1 + Random::GetUint16InRange(0, kMaxResponseDelay)));
   758
   759          LogMleMessage("Delay Link Accept", aMessageInfo.GetPeerAddr());
   760      }

1560  exit:
  1561      return;
  1562  }
  1563
  1564  otError MleRouter::HandleParentRequest(const Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
  1565  {
  1566      otError                 error    = OT_ERROR_NONE;
  1567      const otThreadLinkInfo *linkInfo = static_cast<const otThreadLinkInfo *>(aMessageInfo.GetLinkInfo());
  1568      Mac::ExtAddress         macAddr;
  1569      VersionTlv              version;
  1570      ScanMaskTlv             scanMask;
  1571      ChallengeTlv            challenge;
  1572      Router *                leader;
  1573      Child *                 child;
  1574  #if OPENTHREAD_CONFIG_ENABLE_TIME_SYNC
  1575      TimeRequestTlv timeRequest;
  1576  #endif
  1577
  1578      LogMleMessage("Receive Parent Request", aMessageInfo.GetPeerAddr());
  1579
  1580      VerifyOrExit(IsRouterRoleEnabled(), error = OT_ERROR_INVALID_STATE);
  1581
  1582      // A Router MUST NOT send an MLE Parent Response if:
  1583
  1584      // 0. It is detached or attempting to another partition
  1585      VerifyOrExit((mRole != OT_DEVICE_ROLE_DETACHED) && (mAttachState == kAttachStateIdle), error = OT_ERROR_DROP);
  1586
  1587      // 1. It has no available Child capacity (if Max Child Count minus
  1588      // Child Count would be equal to zero)
  1589      // ==> verified below when allocating a child entry
  1590
  1591      // 2. It is disconnected from its Partition (that is, it has not
  1592      // received an updated ID sequence number within LEADER_TIMEOUT
  1593      // seconds)
  1594      VerifyOrExit(mRouterTable.GetLeaderAge() < mNetworkIdTimeout, error = OT_ERROR_DROP);
  1595
  1596      // 3. Its current routing path cost to the Leader is infinite.
  1597      leader = mRouterTable.GetLeader();
  1598      assert(leader != NULL);
  1599
  1600      VerifyOrExit(mRole == OT_DEVICE_ROLE_LEADER || GetLinkCost(GetLeaderId()) < kMaxRouteCost ||
  1601                       (mRole == OT_DEVICE_ROLE_CHILD && leader->GetCost() + 1 < kMaxRouteCost) ||
  1602                       (leader->GetCost() + GetLinkCost(leader->GetNextHop()) < kMaxRouteCost),
  1603                   error = OT_ERROR_DROP);
  1604
  1605      aMessageInfo.GetPeerAddr().ToExtAddress(macAddr);
  1606
  1607      // Version
  1608      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kVersion, sizeof(version), version));
  1609      VerifyOrExit(version.IsValid() && version.GetVersion() >= kThreadVersion, error = OT_ERROR_PARSE);
  1610
  1611      // Scan Mask
  1612      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kScanMask, sizeof(scanMask), scanMask));
  1613      VerifyOrExit(scanMask.IsValid(), error = OT_ERROR_PARSE);
  1614
  1615      switch (mRole)
  1616      {
  1617      case OT_DEVICE_ROLE_DISABLED:
  1618      case OT_DEVICE_ROLE_DETACHED:
  1619          ExitNow();
  1620
  1621      case OT_DEVICE_ROLE_CHILD:
  1622          VerifyOrExit(scanMask.IsEndDeviceFlagSet());
  1623          break;
  1624
  1625      case OT_DEVICE_ROLE_ROUTER:
  1626      case OT_DEVICE_ROLE_LEADER:
  1627          VerifyOrExit(scanMask.IsRouterFlagSet());
  1628          break;
  1629      }
  1630
  1631      // Challenge
  1632      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kChallenge, sizeof(challenge), challenge));
  1633      VerifyOrExit(challenge.IsValid(), error = OT_ERROR_PARSE);
  1634
  1635      child = GetChildTable().FindChild(macAddr, ChildTable::kInStateAnyExceptInvalid);
  1636
  1637      if (child == NULL)
  1638      {
  1639          VerifyOrExit((child = GetChildTable().GetNewChild()) != NULL);
  1640
  1641          memset(child, 0, sizeof(*child));
  1642
  1643          // MAC Address
  1644          child->SetExtAddress(macAddr);
  1645          child->GetLinkInfo().Clear();
  1646          child->GetLinkInfo().AddRss(GetNetif().GetMac().GetNoiseFloor(), linkInfo->mRss);
  1647          child->ResetLinkFailures();
  1648          child->SetState(Neighbor::kStateParentRequest);
  1649          child->SetDataRequestPending(false);
  1650  #if OPENTHREAD_CONFIG_ENABLE_TIME_SYNC
  1651          if (Tlv::GetTlv(aMessage, Tlv::kTimeRequest, sizeof(timeRequest), timeRequest) == OT_ERROR_NONE)
  1652          {
  1653              child->SetTimeSyncEnabled(true);
  1654          }
  1655          else
  1656          {
  1657              child->SetTimeSyncEnabled(false);
  1658          }
  1659  #endif
  1660      }
  1661      else if ((TimerMilli::GetNow() - child->GetLastHeard()) < kParentRequestRouterTimeout)
  1662      {
  1663          ExitNow(error = OT_ERROR_DUPLICATED);
  1664      }
  1665
  1666      if (!child->IsStateValidOrRestoring())
  1667      {
  1668          child->SetLastHeard(TimerMilli::GetNow());
  1669          child->SetTimeout(TimerMilli::MsecToSec(kMaxChildIdRequestTimeout));
  1670      }
  1671
  1672      SendParentResponse(child, challenge, !scanMask.IsEndDeviceFlagSet());
  1673
  1674  exit:
  1675      return error;
  1676  }
