  2060  otError MleRouter::HandleChildIdRequest(const Message &         aMessage,
  2061                                          const Ip6::MessageInfo &aMessageInfo,
  2062                                          uint32_t                aKeySequence)
  2063  {
  2064      ThreadNetif &           netif    = GetNetif();
  2065      otError                 error    = OT_ERROR_NONE;
  2066      const otThreadLinkInfo *linkInfo = static_cast<const otThreadLinkInfo *>(aMessageInfo.GetLinkInfo());
  2067      Mac::ExtAddress         macAddr;
  2068      ResponseTlv             response;
  2069      LinkFrameCounterTlv     linkFrameCounter;
  2070      MleFrameCounterTlv      mleFrameCounter;
  2071      ModeTlv                 mode;
  2072      TimeoutTlv              timeout;
  2073      TlvRequestTlv           tlvRequest;
  2074      ActiveTimestampTlv      activeTimestamp;
  2075      PendingTimestampTlv     pendingTimestamp;
  2076      Child *                 child;
