  2078      uint8_t                 numTlvs;
  2079      uint16_t                addressRegistrationOffset = 0;
  2080
  2081      LogMleMessage("Receive Child ID Request", aMessageInfo.GetPeerAddr());
  2082
  2083      VerifyOrExit(IsRouterRoleEnabled(), error = OT_ERROR_INVALID_STATE);
  2084
  2085      // only process message when operating as a child, router, or leader
  2086      VerifyOrExit(IsAttached(), error = OT_ERROR_INVALID_STATE);
  2087
  2088      // Find Child
  2089      aMessageInfo.GetPeerAddr().ToExtAddress(macAddr);
  2090
  2091      child = GetChildTable().FindChild(macAddr, ChildTable::kInStateAnyExceptInvalid);
  2092      VerifyOrExit(child != NULL, error = OT_ERROR_ALREADY);
  2093
  2094      // Response
  2095      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kResponse, sizeof(response), response));
  2096      VerifyOrExit(response.IsValid() &&
  2097                       memcmp(response.GetResponse(), child->GetChallenge(), child->GetChallengeSize()) == 0,
  2098                   error = OT_ERROR_SECURITY);
  2099
  2100      // Remove existing MLE messages
  2101      netif.GetMeshForwarder().RemoveMessages(*child, Message::kSubTypeMleGeneral);
  2102      netif.GetMeshForwarder().RemoveMessages(*child, Message::kSubTypeMleChildUpdateRequest);
  2103      netif.GetMeshForwarder().RemoveMessages(*child, Message::kSubTypeMleDataResponse);
  2104
  2105      // Link-Layer Frame Counter
  2106      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kLinkFrameCounter, sizeof(linkFrameCounter), linkFrameCounter));
  2107      VerifyOrExit(linkFrameCounter.IsValid(), error = OT_ERROR_PARSE);
  2108
  2109      // MLE Frame Counter
  2110      if (Tlv::GetTlv(aMessage, Tlv::kMleFrameCounter, sizeof(mleFrameCounter), mleFrameCounter) == OT_ERROR_NONE)
  2111      {
  2112          VerifyOrExit(mleFrameCounter.IsValid(), error = OT_ERROR_PARSE);
  2113      }
  2114      else
  2115      {
  2116          mleFrameCounter.SetFrameCounter(linkFrameCounter.GetFrameCounter());
  2117      }
  2118
  2119      // Mode
  2120      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kMode, sizeof(mode), mode));
  2121      VerifyOrExit(mode.IsValid(), error = OT_ERROR_PARSE);
  2122
  2123      // Timeout
  2124      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kTimeout, sizeof(timeout), timeout));
  2125      VerifyOrExit(timeout.IsValid(), error = OT_ERROR_PARSE);
  2126
  2127      // TLV Request
  2128      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kTlvRequest, sizeof(tlvRequest), tlvRequest));
  2129      VerifyOrExit(tlvRequest.IsValid() && tlvRequest.GetLength() <= Child::kMaxRequestTlvs, error = OT_ERROR_PARSE);
  2130
  2131      // Active Timestamp
  2132      activeTimestamp.SetLength(0);
  2133
  2134      if (Tlv::GetTlv(aMessage, Tlv::kActiveTimestamp, sizeof(activeTimestamp), activeTimestamp) == OT_ERROR_NONE)
  2135      {
  2136          VerifyOrExit(activeTimestamp.IsValid(), error = OT_ERROR_PARSE);
  2137      }
  2138
  2139      // Pending Timestamp
  2140      pendingTimestamp.SetLength(0);
  2141
  2142      if (Tlv::GetTlv(aMessage, Tlv::kPendingTimestamp, sizeof(pendingTimestamp), pendingTimestamp) == OT_ERROR_NONE)
  2143      {
  2144          VerifyOrExit(pendingTimestamp.IsValid(), error = OT_ERROR_PARSE);
  2145      }
  2146
  2147      if ((mode.GetMode() & ModeTlv::kModeFullThreadDevice) == 0)
  2148      {
  2149          SuccessOrExit(error = Tlv::GetOffset(aMessage, Tlv::kAddressRegistration, addressRegistrationOffset));
  2150          SuccessOrExit(error = UpdateChildAddresses(aMessage, addressRegistrationOffset, *child));
  2151      }
  2152
  2153      // Remove from router table
  2154      router = mRouterTable.GetRouter(macAddr);
  2155      if (router != NULL)
  2156      {
  2157          RemoveNeighbor(*router);
  2158      }
  2159
  2160      if (child->GetState() != Neighbor::kStateValid)
  2161      {
  2162          child->SetState(Neighbor::kStateChildIdRequest);
  2163      }
  2164      else
  2165      {
  2166          RemoveNeighbor(*child);
  2167      }
  2168
  2169      child->SetLastHeard(TimerMilli::GetNow());
  2170      child->SetLinkFrameCounter(linkFrameCounter.GetFrameCounter());
  2171      child->SetMleFrameCounter(mleFrameCounter.GetFrameCounter());
  2172      child->SetKeySequence(aKeySequence);
  2173      child->SetDeviceMode(mode.GetMode());
  2174      child->GetLinkInfo().AddRss(netif.GetMac().GetNoiseFloor(), linkInfo->mRss);
  2175      child->SetTimeout(timeout.GetTimeout());
  2176
  2177      if (mode.GetMode() & ModeTlv::kModeFullNetworkData)
  2178      {
  2179          child->SetNetworkDataVersion(mLeaderData.GetDataVersion());
  2180      }
  2181      else
  2182      {
  2183          child->SetNetworkDataVersion(mLeaderData.GetStableDataVersion());
  2184      }
  2185
  2186      child->ClearRequestTlvs();
  2187
  2188      for (numTlvs = 0; numTlvs < tlvRequest.GetLength(); numTlvs++)
  2189      {
  2190          child->SetRequestTlv(numTlvs, tlvRequest.GetTlvs()[numTlvs]);
  2191      }
  2192
  2193      if (activeTimestamp.GetLength() == 0 || netif.GetActiveDataset().Compare(activeTimestamp) != 0)
  2194      {
  2195          child->SetRequestTlv(numTlvs++, Tlv::kActiveDataset);
  2196      }
  2197
  2198      if (pendingTimestamp.GetLength() == 0 || netif.GetPendingDataset().Compare(pendingTimestamp) != 0)
  2199      {
  2200          child->SetRequestTlv(numTlvs++, Tlv::kPendingDataset);
  2201      }
  2202
  2203      switch (mRole)
  2204      {
  2205      case OT_DEVICE_ROLE_DISABLED:
  2206      case OT_DEVICE_ROLE_DETACHED:
  2207          assert(false);
  2208          break;
  2209
  2210      case OT_DEVICE_ROLE_CHILD:
  2211          child->SetState(Neighbor::kStateChildIdRequest);
  2212          BecomeRouter(ThreadStatusTlv::kHaveChildIdRequest);
  2213          break;
  2214
  2215      case OT_DEVICE_ROLE_ROUTER:
  2216      case OT_DEVICE_ROLE_LEADER:
  2217          SuccessOrExit(error = SendChildIdResponse(*child));
  2218          break;
  2219      }
  2220
  2221  exit:
  2222      return error;
  2223  }
