  2565          uint8_t version;
  2566
  2567          if (child.IsRxOnWhenIdle())
  2568          {
  2569              continue;
  2570          }
  2571
  2572          if (child.IsFullNetworkData())
  2573          {
  2574              version = netif.GetNetworkDataLeader().GetVersion();
