  2576          else
  2577          {
  2578              version = netif.GetNetworkDataLeader().GetStableVersion();
  2579          }
  2580
  2581          if (child.GetNetworkDataVersion() == version)
  2582          {
  2583              continue;
  2584          }
  2585
  2586          SuccessOrExit(SendChildUpdateRequest(child));
  2587      }
