  2307      }
  2308
  2309      // Leader Data
  2310      if (Tlv::GetTlv(aMessage, Tlv::kLeaderData, sizeof(leaderData), leaderData) == OT_ERROR_NONE)
  2311      {
  2312          VerifyOrExit(leaderData.IsValid(), error = OT_ERROR_PARSE);
  2313      }
  2314
  2315      // Timeout
  2316      if (Tlv::GetTlv(aMessage, Tlv::kTimeout, sizeof(timeout), timeout) == OT_ERROR_NONE)
  2317      {
  2318          VerifyOrExit(timeout.IsValid(), error = OT_ERROR_PARSE);
  2319
  2320          if (child->GetTimeout() != timeout.GetTimeout())
  2321          {
  2322              child->SetTimeout(timeout.GetTimeout());
  2323              childDidChange = true;
  2324          }
  2325
  2326          tlvs[tlvslength++] = Tlv::kTimeout;
  2327      }
