  2369  otError MleRouter::HandleChildUpdateResponse(const Message &         aMessage,
  2370                                               const Ip6::MessageInfo &aMessageInfo,
  2371                                               uint32_t                aKeySequence)
  2372  {
  2373      otError                 error    = OT_ERROR_NONE;
  2374      const otThreadLinkInfo *linkInfo = static_cast<const otThreadLinkInfo *>(aMessageInfo.GetLinkInfo());
  2375      Mac::ExtAddress         macAddr;
  2376      SourceAddressTlv        sourceAddress;
  2377      TimeoutTlv              timeout;
  2378      ResponseTlv             response;
  2379      StatusTlv               status;
  2380      LinkFrameCounterTlv     linkFrameCounter;
  2381      MleFrameCounterTlv      mleFrameCounter;
  2382      LeaderDataTlv           leaderData;
  2383      Child *                 child;
  2384      uint16_t                addressRegistrationOffset = 0;
  2385
  2386      // Find Child
  2387      aMessageInfo.GetPeerAddr().ToExtAddress(macAddr);
  2388
  2389      child = GetChildTable().FindChild(macAddr, ChildTable::kInStateAnyExceptInvalid);
  2390
  2391      if (child == NULL)
  2392      {
  2393          LogMleMessage("Receive Child Update Response from unknown child", aMessageInfo.GetPeerAddr());
  2394          ExitNow(error = OT_ERROR_NOT_FOUND);
  2395      }
  2396
  2397      // Source Address
  2398      if (Tlv::GetTlv(aMessage, Tlv::kSourceAddress, sizeof(sourceAddress), sourceAddress) == OT_ERROR_NONE)
  2399      {
  2400          VerifyOrExit(sourceAddress.IsValid(), error = OT_ERROR_PARSE);
  2401
  2402          if (child->GetRloc16() != sourceAddress.GetRloc16())
  2403          {
  2404              LogMleMessage("Receive Child Update Response from unknown child", aMessageInfo.GetPeerAddr(),
  2405                            sourceAddress.GetRloc16());
  2406              ExitNow(error = OT_ERROR_PARSE);
  2407          }
  2408      }
  2409
  2410      LogMleMessage("Receive Child Update Response from child", aMessageInfo.GetPeerAddr(), child->GetRloc16());
  2411
  2412      // Response
  2413      if (Tlv::GetTlv(aMessage, Tlv::kResponse, sizeof(response), response) == OT_ERROR_NONE)
  2414      {
  2415          VerifyOrExit(response.IsValid() &&
  2416                           memcmp(response.GetResponse(), child->GetChallenge(), child->GetChallengeSize()) == 0,
  2417                       error = OT_ERROR_SECURITY);
  2418      }
  2419
  2420      // Status
  2421      if (Tlv::GetTlv(aMessage, Tlv::kStatus, sizeof(status), status) == OT_ERROR_NONE)
  2422      {
  2423          VerifyOrExit(status.IsValid(), error = OT_ERROR_PARSE);
  2424
  2425          if (status.GetStatus() == StatusTlv::kError)
  2426          {
  2427              RemoveNeighbor(*child);
  2428              ExitNow();
  2429          }
  2430      }
  2431
  2432      // Link-Layer Frame Counter
  2433      if (Tlv::GetTlv(aMessage, Tlv::kLinkFrameCounter, sizeof(linkFrameCounter), linkFrameCounter) == OT_ERROR_NONE)
  2434      {
  2435          VerifyOrExit(linkFrameCounter.IsValid(), error = OT_ERROR_PARSE);
  2436          child->SetLinkFrameCounter(linkFrameCounter.GetFrameCounter());
  2437      }
  2438
  2439      // MLE Frame Counter
  2440      if (Tlv::GetTlv(aMessage, Tlv::kMleFrameCounter, sizeof(mleFrameCounter), mleFrameCounter) == OT_ERROR_NONE)
  2441      {
  2442          VerifyOrExit(mleFrameCounter.IsValid(), error = OT_ERROR_PARSE);
  2443          child->SetMleFrameCounter(mleFrameCounter.GetFrameCounter());
  2444      }
  2445
  2446      // Timeout
  2447      if (Tlv::GetTlv(aMessage, Tlv::kTimeout, sizeof(timeout), timeout) == OT_ERROR_NONE)
  2448      {
  2449          VerifyOrExit(timeout.IsValid(), error = OT_ERROR_PARSE);
  2450          child->SetTimeout(timeout.GetTimeout());
  2451      }
  2452
  2453      // Ip6 Address
  2454      if (Tlv::GetOffset(aMessage, Tlv::kAddressRegistration, addressRegistrationOffset) == OT_ERROR_NONE)
  2455      {
  2456          SuccessOrExit(error = UpdateChildAddresses(aMessage, addressRegistrationOffset, *child));
  2457      }
  2458
  2459      // Leader Data
  2460      if (Tlv::GetTlv(aMessage, Tlv::kLeaderData, sizeof(leaderData), leaderData) == OT_ERROR_NONE)
  2461      {
  2462          VerifyOrExit(leaderData.IsValid(), error = OT_ERROR_PARSE);
  2463
  2464          if (child->IsFullNetworkData())
  2465          {
  2466              child->SetNetworkDataVersion(leaderData.GetDataVersion());
  2467          }
  2468          else
  2469          {
  2470              child->SetNetworkDataVersion(leaderData.GetStableDataVersion());
  2471          }
  2472      }
  2473
  2474      SetChildStateToValid(*child);
  2475      child->SetLastHeard(TimerMilli::GetNow());
  2476      child->SetKeySequence(aKeySequence);
  2477      child->GetLinkInfo().AddRss(GetNetif().GetMac().GetNoiseFloor(), linkInfo->mRss);
  2478
  2479  exit:
  2480      return error;
  2481  }
